#!/usr/bin/env python3
"""Frozen PF-SNRE core used after Direct Set-NRE V2.

This module deliberately preserves the V2 network topology while removing all
H01/source-count/block-schedule hard-coding. The canonical block manifest is an
input contract; this module never reconstructs PMFS callback boundaries from
heuristics.

Scientific semantics:
  * observation and candidate predictions are both in measured-sensor space;
  * candidate predictions must have been generated by advancing the persistent
    sensor state over the full 0.2 s trajectory, including movement gaps;
  * nuisance members and visible sensing blocks are aggregated as sets;
  * block acquisition context is retained, so this is not a claim of complete
    time/order removal;
  * the scalar network output is an NRE likelihood-ratio factor;
  * q0 is applied only after scoring.
"""
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
import hashlib
import json
import math

import numpy as np
import torch
from torch import nn

REFERENCE_PPM = 0.1
BLOCK_SAMPLES = 10
EXPECTED_TRAIN_MEMBERS = 8


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def log_measurement(values) -> np.ndarray:
    v = np.asarray(values, dtype=np.float32)
    if np.any(v < 0) or not np.all(np.isfinite(v)):
        raise ValueError("measured ppm must be finite and nonnegative")
    return np.log1p(v / REFERENCE_PPM).astype(np.float32)


@dataclass(frozen=True)
class CanonicalBlocks:
    """Authoritative block/update support for one House.

    Invalid padded entries must be -1. `update_visible_blocks[n,u]` is the exact
    number of completed blocks causally visible at update u+1, or 0 if absent.
    """
    sample_indices: np.ndarray        # [N,Bmax,10]
    block_count: np.ndarray           # [N]
    stop_index: np.ndarray            # [N,Bmax]
    block_within_stop: np.ndarray     # [N,Bmax]
    stop_x: np.ndarray                # [N,Bmax]
    stop_y: np.ndarray                # [N,Bmax]
    update_visible_blocks: np.ndarray # [N,Umax]
    trajectory_sha: np.ndarray        # [N]

    @classmethod
    def load(cls, path: Path) -> "CanonicalBlocks":
        with np.load(path, allow_pickle=False) as d:
            required = (
                "sample_indices", "block_count", "stop_index", "block_within_stop",
                "stop_x", "stop_y", "update_visible_blocks", "trajectory_sha",
            )
            missing = [k for k in required if k not in d]
            if missing:
                raise ValueError(f"{path}: missing canonical block arrays {missing}")
            obj = cls(*(np.asarray(d[k]) for k in required))
        obj.validate()
        return obj

    def validate(self) -> None:
        idx = np.asarray(self.sample_indices)
        if idx.ndim != 3 or idx.shape[2] != BLOCK_SAMPLES:
            raise ValueError("sample_indices must be [trajectory,block,10]")
        n, bmax, _ = idx.shape
        for name, arr in (
            ("block_count", self.block_count), ("stop_index", self.stop_index),
            ("block_within_stop", self.block_within_stop), ("stop_x", self.stop_x),
            ("stop_y", self.stop_y), ("update_visible_blocks", self.update_visible_blocks),
            ("trajectory_sha", self.trajectory_sha),
        ):
            if np.asarray(arr).shape[0] != n:
                raise ValueError(f"{name}: trajectory dimension mismatch")
        if np.asarray(self.stop_index).shape != (n, bmax):
            raise ValueError("stop_index shape mismatch")
        if np.asarray(self.block_within_stop).shape != (n, bmax):
            raise ValueError("block_within_stop shape mismatch")
        if np.asarray(self.stop_x).shape != (n, bmax) or np.asarray(self.stop_y).shape != (n, bmax):
            raise ValueError("stop coordinate shape mismatch")
        counts = np.asarray(self.block_count, dtype=np.int64)
        if np.any(counts <= 0) or np.any(counts > bmax):
            raise ValueError("invalid block_count")
        for t, count in enumerate(counts):
            used = idx[t, :count]
            if np.any(used < 0) or np.any(np.diff(used, axis=1) != 1):
                raise ValueError(f"trajectory {t}: each block must contain 10 consecutive valid rows")
            if len(np.unique(used)) != used.size:
                raise ValueError(f"trajectory {t}: sensing samples reused across blocks")
            if count < bmax and np.any(idx[t, count:] != -1):
                raise ValueError(f"trajectory {t}: padded sample indices must be -1")
            updates = np.asarray(self.update_visible_blocks[t], dtype=np.int64)
            positive = updates[updates > 0]
            if positive.size and (np.any(np.diff(positive) <= 0) or positive[-1] > count):
                raise ValueError(f"trajectory {t}: update prefix is not strictly causal/increasing")
        shas = np.asarray(self.trajectory_sha).astype(str)
        if len(set(shas.tolist())) != len(shas) or any(not s for s in shas):
            raise ValueError("trajectory_sha must be nonempty and unique")

    def visible(self, trajectory: int, update: int) -> int:
        if trajectory < 0 or trajectory >= len(self.block_count) or update < 1:
            raise IndexError("trajectory/update out of range")
        u = update - 1
        if u >= self.update_visible_blocks.shape[1]:
            raise ValueError("source update unavailable")
        visible = int(self.update_visible_blocks[trajectory, u])
        if visible <= 0:
            raise ValueError("source update unavailable")
        return visible


@dataclass
class HouseDataset:
    house: str
    measured: np.ndarray              # [S,8,N,Tmax], persistent-sensor measured ppm
    carriers: list[dict]
    blocks: CanonicalBlocks
    xy_center: np.ndarray
    xy_scale: np.ndarray
    prior: np.ndarray

    @classmethod
    def load(cls, house: str, measured_path: Path, carriers_path: Path, blocks_path: Path) -> "HouseDataset":
        measured = np.load(measured_path, mmap_mode="r")
        carriers = json.loads(Path(carriers_path).read_text(encoding="utf-8"))
        blocks = CanonicalBlocks.load(Path(blocks_path))
        if measured.ndim != 4:
            raise ValueError(f"{house}: measured must be [S,M,N,T]")
        s, m, n, tmax = measured.shape
        if m != EXPECTED_TRAIN_MEMBERS:
            raise ValueError(f"{house}: expected exactly {EXPECTED_TRAIN_MEMBERS} predictive members, got {m}")
        if s != len(carriers) or n != len(blocks.block_count):
            raise ValueError(f"{house}: measured/carrier/block dimensions disagree")
        if not np.issubdtype(measured.dtype, np.floating):
            raise ValueError(f"{house}: measured array must be floating point")
        for trajectory in range(n):
            count = int(blocks.block_count[trajectory])
            max_row = int(np.max(blocks.sample_indices[trajectory, :count]))
            if max_row >= tmax:
                raise ValueError(f"{house}: trajectory {trajectory} block index exceeds measured T")
        required = {"carrier_id", "centroid_x", "centroid_y", "width_m", "height_m", "free_count", "prior_mass"}
        ids = []
        prior = []
        xy = []
        for i, c in enumerate(carriers):
            missing = required - set(c)
            if missing:
                raise ValueError(f"{house}: carrier {i} missing {sorted(missing)}")
            ids.append(str(c["carrier_id"]))
            xy.append([float(c["centroid_x"]), float(c["centroid_y"])])
            prior.append(float(c["prior_mass"]))
            if int(c["free_count"]) <= 0:
                raise ValueError(f"{house}: carrier {ids[-1]} has no free cells")
        if len(set(ids)) != len(ids):
            raise ValueError(f"{house}: duplicate carrier IDs")
        prior = np.asarray(prior, dtype=np.float64)
        if np.any(prior <= 0) or not np.isfinite(prior).all():
            raise ValueError(f"{house}: q0 must be finite positive")
        prior /= prior.sum()
        free = np.asarray([int(c["free_count"]) for c in carriers], dtype=np.float64)
        q0_area = free / free.sum()
        if np.max(np.abs(prior - q0_area)) > 1e-12:
            raise ValueError(f"{house}: q0 is not proportional to free-cell area")
        xy = np.asarray(xy, dtype=np.float64)
        center = 0.5 * (xy.min(axis=0) + xy.max(axis=0))
        extent = xy.max(axis=0) - xy.min(axis=0)
        if np.any(extent <= 1e-6):
            raise ValueError(f"{house}: carrier support must span both x and y for frozen V2 normalization")
        scale = extent
        return cls(house, measured, carriers, blocks, center, scale, prior)

    @property
    def source_count(self) -> int:
        return len(self.carriers)

    @property
    def trajectory_count(self) -> int:
        return self.measured.shape[2]


def candidate_features(carrier: dict, xy_center: np.ndarray, xy_scale: np.ndarray) -> np.ndarray:
    cx, cy = float(carrier["centroid_x"]), float(carrier["centroid_y"])
    return np.asarray([
        (cx - xy_center[0]) / xy_scale[0],
        (cy - xy_center[1]) / xy_scale[1],
        float(carrier["width_m"]) / xy_scale[0],
        float(carrier["height_m"]) / xy_scale[1],
        math.log1p(float(carrier["free_count"])) / math.log(5.0),
    ], dtype=np.float32)


def block_context(data: HouseDataset, trajectory: int, visible: int, candidate: int) -> np.ndarray:
    blocks = data.blocks
    carrier = data.carriers[candidate]
    cx, cy = float(carrier["centroid_x"]), float(carrier["centroid_y"])
    sx = np.asarray(blocks.stop_x[trajectory, :visible], dtype=np.float32)
    sy = np.asarray(blocks.stop_y[trajectory, :visible], dtype=np.float32)
    stop = np.asarray(blocks.stop_index[trajectory, :visible], dtype=np.float32)
    within = np.asarray(blocks.block_within_stop[trajectory, :visible], dtype=np.float32)
    max_stop = max(float(np.max(stop)), 1.0)
    return np.column_stack([
        (sx - data.xy_center[0]) / data.xy_scale[0],
        (sy - data.xy_center[1]) / data.xy_scale[1],
        (cx - sx) / data.xy_scale[0],
        (cy - sy) / data.xy_scale[1],
        2.0 * within / 7.0 - 1.0,
        stop / max_stop,
    ]).astype(np.float32)


def masked_moments(x: torch.Tensor, mask: torch.Tensor, dim: int):
    """V2's exact permutation-invariant moment pooling (not CIGaRS SetNorm)."""
    m = mask.to(x.dtype)
    while m.ndim < x.ndim:
        m = m.unsqueeze(-1)
    count = m.sum(dim=dim).clamp_min(1.0)
    total = (x * m).sum(dim=dim)
    mean = total / count
    centered = (x - mean.unsqueeze(dim)) * m
    var = (centered * centered).sum(dim=dim) / count
    neg = torch.finfo(x.dtype).min
    maximum = x.masked_fill(~m.bool(), neg).amax(dim=dim)
    sqrt_sum = total / torch.sqrt(count)
    return mean, maximum, torch.sqrt(var.clamp_min(0.0) + 1e-8), sqrt_sum


class ConditionedMomentSetDirectNRE(nn.Module):
    """Exact V2 topology, renamed to avoid claiming CIGaRS's SetNorm/Deep Set++ implementation."""
    def __init__(self, candidate_dim: int = 5, block_context_dim: int = 6, hidden: int = 32):
        super().__init__()
        self.candidate_dim = candidate_dim
        self.block_context_dim = block_context_dim
        self.hidden = hidden
        self.member_encoder = nn.Sequential(
            nn.Linear(40, hidden), nn.SiLU(), nn.Linear(hidden, hidden), nn.SiLU())
        self.block_encoder = nn.Sequential(
            nn.Linear(4 * hidden + 4 + block_context_dim + candidate_dim, 64),
            nn.SiLU(), nn.Linear(64, hidden), nn.SiLU())
        self.head = nn.Sequential(
            nn.Linear(4 * hidden + 1 + candidate_dim, 64), nn.SiLU(),
            nn.Linear(64, 32), nn.SiLU(), nn.Linear(32, 1))

    def forward(self, observation, prediction_set, block_context_tensor,
                candidate, block_mask, member_mask):
        obs = observation.unsqueeze(2).expand_as(prediction_set)
        member_input = torch.cat(
            [obs, prediction_set, obs - prediction_set, torch.abs(obs - prediction_set)], dim=-1)
        encoded = self.member_encoder(member_input)
        mm = member_mask[:, None, :].expand(-1, prediction_set.shape[1], -1)
        member_pool = torch.cat(masked_moments(encoded, mm, dim=2), dim=-1)
        obs_mean = observation.mean(dim=-1, keepdim=True)
        obs_std = observation.std(dim=-1, correction=0, keepdim=True)
        obs_slope = (observation[..., -1:] - observation[..., :1]) / 9.0
        obs_max = observation.amax(dim=-1, keepdim=True)
        cand = candidate[:, None, :].expand(-1, observation.shape[1], -1)
        block_input = torch.cat([
            member_pool, obs_mean, obs_std, obs_slope, obs_max,
            block_context_tensor, cand], dim=-1)
        block_encoded = self.block_encoder(block_input)
        block_pool = torch.cat(masked_moments(block_encoded, block_mask, dim=1), dim=-1)
        count = block_mask.sum(dim=1, keepdim=True).to(observation.dtype)
        return self.head(torch.cat([block_pool, torch.log1p(count), candidate], dim=-1)).squeeze(-1)


def direct_posterior(geometry_prior, log_likelihood_ratio) -> np.ndarray:
    q = np.asarray(geometry_prior, dtype=np.float64)
    r = np.asarray(log_likelihood_ratio, dtype=np.float64)
    if q.ndim != 1 or q.shape != r.shape or np.any(q <= 0) or not np.all(np.isfinite(r)):
        raise ValueError("invalid direct posterior inputs")
    q = q / q.sum()
    z = np.log(q) + r
    z -= np.max(z)
    p = np.exp(z)
    return p / p.sum()
